package repository

import (
	"context"
	"database/sql"
	"fmt"
	"log/slog"
	"strconv"
	"strings"
	"time"

	"meko/api_server/internal/models"
)

// FeedbackRepo persists rows to meko_system.feedback.
type FeedbackRepo struct {
	db *sql.DB
}

// NewFeedbackRepo constructs a FeedbackRepo.
func NewFeedbackRepo(db *sql.DB) *FeedbackRepo {
	return &FeedbackRepo{db: db}
}

// CreateFeedbackParams holds validated insert fields. id is generated by the
// database (GENERATED ALWAYS AS IDENTITY).
type CreateFeedbackParams struct {
	CreatedAt        *time.Time
	UserID           string
	Source           string
	SourceIdentifier *string
	DatapackID       *string
	DatapackName     *string
	ContextRoute     *string
	Category         string
	Body             string
	MekoVersion      *string
}

// Create inserts one feedback row and returns the generated BIGINT id.
func (r *FeedbackRepo) Create(p CreateFeedbackParams) (int64, error) {
	var datapackID interface{}
	if p.DatapackID != nil && strings.TrimSpace(*p.DatapackID) != "" {
		datapackID = strings.TrimSpace(*p.DatapackID)
	} else {
		datapackID = nil
	}

	var datapackName interface{}
	if p.DatapackName != nil && strings.TrimSpace(*p.DatapackName) != "" {
		datapackName = strings.TrimSpace(*p.DatapackName)
	} else {
		datapackName = nil
	}

	var sourceID interface{}
	if p.SourceIdentifier != nil && strings.TrimSpace(*p.SourceIdentifier) != "" {
		sourceID = strings.TrimSpace(*p.SourceIdentifier)
	} else {
		sourceID = nil
	}

	var ctxRoute interface{}
	if p.ContextRoute != nil && strings.TrimSpace(*p.ContextRoute) != "" {
		ctxRoute = strings.TrimSpace(*p.ContextRoute)
	} else {
		ctxRoute = nil
	}

	var mekoVer interface{}
	if p.MekoVersion != nil && strings.TrimSpace(*p.MekoVersion) != "" {
		mekoVer = strings.TrimSpace(*p.MekoVersion)
	} else {
		mekoVer = nil
	}

	var createdAt interface{}
	if p.CreatedAt != nil {
		createdAt = *p.CreatedAt
	} else {
		createdAt = nil
	}

	var id int64
	err := r.db.QueryRow(
		`INSERT INTO meko_system.feedback (
			created_at, updated_at, user_id, source, source_identifier,
			datapack_id, datapack_name, context_route, category, body, meko_version
		) VALUES (
			COALESCE($1::timestamptz, NOW()),
			NOW(),
			$2::uuid,
			$3::meko_system.feedback_source,
			$4,
			$5::uuid,
			$6,
			$7,
			$8::meko_system.feedback_category,
			$9,
			$10
		)
		RETURNING id`,
		createdAt,
		p.UserID,
		p.Source,
		sourceID,
		datapackID,
		datapackName,
		ctxRoute,
		p.Category,
		p.Body,
		mekoVer,
	).Scan(&id)
	if err != nil {
		slog.Error("failed to insert feedback", "error", err)
		return 0, fmt.Errorf("failed to insert feedback: %w", err)
	}
	return id, nil
}

const feedbackListMaxRows = 500

// ListFeedback filters meko_system.feedback. At least one of userID or status must be non-empty
// (enforced by the handler).
func (r *FeedbackRepo) ListFeedback(ctx context.Context, userID, status *string) ([]models.FeedbackListItem, error) {
	base := `
		SELECT
			id,
			created_at,
			updated_at,
			user_id::text,
			source::text,
			source_identifier,
			datapack_id::text,
			datapack_name,
			context_route,
			category::text,
			body,
			meko_version,
			status::text
		FROM meko_system.feedback
		WHERE 1=1
	`
	var args []interface{}
	n := 1
	if userID != nil && strings.TrimSpace(*userID) != "" {
		base += fmt.Sprintf(" AND user_id = $%d::uuid", n)
		args = append(args, strings.TrimSpace(*userID))
		n++
	}
	if status != nil && strings.TrimSpace(*status) != "" {
		base += fmt.Sprintf(" AND status = $%d::meko_system.feedback_status", n)
		args = append(args, strings.TrimSpace(*status))
		n++
	}
	base += fmt.Sprintf(`
		ORDER BY created_at DESC
		LIMIT %d`, feedbackListMaxRows)

	rows, err := r.db.QueryContext(ctx, base, args...)
	if err != nil {
		slog.Error("feedback list query failed", "error", err)
		return nil, fmt.Errorf("list feedback: %w", err)
	}
	defer func() { _ = rows.Close() }()

	var out []models.FeedbackListItem
	for rows.Next() {
		var (
			id        int64
			createdAt time.Time
			updatedAt sql.NullTime
			userUUID  sql.NullString
			source    string
			srcID     sql.NullString
			dpID      sql.NullString
			dpName    sql.NullString
			ctxRoute  sql.NullString
			category  string
			body      string
			mekoVer   sql.NullString
			st        string
		)
		if scanErr := rows.Scan(
			&id,
			&createdAt,
			&updatedAt,
			&userUUID,
			&source,
			&srcID,
			&dpID,
			&dpName,
			&ctxRoute,
			&category,
			&body,
			&mekoVer,
			&st,
		); scanErr != nil {
			return nil, fmt.Errorf("scan feedback row: %w", scanErr)
		}

		it := models.FeedbackListItem{
			ID:        strconv.FormatInt(id, 10),
			CreatedAt: createdAt,
			Source:    source,
			Category:  category,
			Body:      body,
			Status:    st,
		}
		if updatedAt.Valid {
			tm := updatedAt.Time
			it.UpdatedAt = &tm
		}
		if userUUID.Valid && strings.TrimSpace(userUUID.String) != "" {
			u := userUUID.String
			it.UserID = &u
		}
		if srcID.Valid && strings.TrimSpace(srcID.String) != "" {
			s := srcID.String
			it.SourceIdentifier = &s
		}
		if dpID.Valid && strings.TrimSpace(dpID.String) != "" {
			d := dpID.String
			it.DatapackID = &d
		}
		if dpName.Valid && strings.TrimSpace(dpName.String) != "" {
			d := dpName.String
			it.DatapackName = &d
		}
		if ctxRoute.Valid && strings.TrimSpace(ctxRoute.String) != "" {
			c := ctxRoute.String
			it.ContextRoute = &c
		}
		if mekoVer.Valid && strings.TrimSpace(mekoVer.String) != "" {
			m := mekoVer.String
			it.MekoVersion = &m
		}
		out = append(out, it)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("feedback list rows: %w", err)
	}
	return out, nil
}
